import{_ as o,o as t,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月10日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-10.md","filePath":"science-log/src/reconstructed/2026-09-10.md"}'),s={name:"science-log/src/reconstructed/2026-09-10.md"};function a(g,r,i,l,c,d){return t(),n("div",null,[...r[0]||(r[0]=[e('<h1 id="🔬-科学快报-2026年9月10日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月10日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月10日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月10日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-10 为<strong>周四</strong>。CrossRef 当日命中：Nature（0028-0836）仅 6 条，其中<strong>唯一一条 <code>s41586</code> 为 Author Correction（更正，非研究论文）</strong>，其余全为 <code>10.1038/d41586-…</code> 新闻/Briefing —— 故本日科学版<strong>不取 Nature</strong>；Science 系（10.1126）当日命中 40 余条（含大量新闻与社论，已剔除 <code>z…</code> 新闻稿），研究论文充足；PNAS（0027-8424）当日命中 10 条研究论文。<strong>科学 5 篇</strong>取自 Science / PNAS 当日（<code>published</code> = 2026-09-10）研究论文；<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（submittedDate <code>[202609100000 TO 202609102359]</code> 命中 30 篇，恰好触及 max_results 上限）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧫-未磷酸化的酪氨酸才是-pd-1-的刹车-抑制信号靠凝聚体解聚而非磷酸化" tabindex="-1">🧫 未磷酸化的酪氨酸才是 PD-1 的刹车：抑制信号靠凝聚体解聚而非磷酸化 <a class="header-anchor" href="#🧫-未磷酸化的酪氨酸才是-pd-1-的刹车-抑制信号靠凝聚体解聚而非磷酸化" aria-label="Permalink to &quot;🧫 未磷酸化的酪氨酸才是 PD-1 的刹车：抑制信号靠凝聚体解聚而非磷酸化&quot;">​</a></h3><p><strong>Unphosphorylated tyrosines mediate PD-1 inhibition of T cell signaling condensate formation</strong><em>Science（2026）</em></p><p>免疫检查点 PD-1 如何抑制 T 细胞信号，长期被解释为&quot;磷酸化后募集磷酸酶 SHP2&quot;。本文用体外重构提出<strong>反直觉的机制</strong>：PD-1 胞质域<strong>直接抑制</strong> T 细胞受体（TCR）诱导的 <strong>LAT 生物分子凝聚体</strong>形成；这一抑制<strong>依赖 PD-1 两个抑制基序上的酪氨酸残基</strong>，但——与主流模型相反——<strong>酪氨酸一旦被磷酸化，PD-1 的抑制作用反而消失</strong>。作者把酪氨酸换成色氨酸后抑制能力得以重建，证明起关键作用的是<strong>能提供氢键的芳香族残基本身</strong>，而非磷酸化修饰。这为&quot;抑制性受体如何拆解信号网络&quot;给出了一个以**残基化学（氢键供体）**而非磷酸化为主导的新范式。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adt9365" target="_blank" rel="noreferrer">10.1126/science.adt9365</a></p><h3 id="🦣-披毛犀起源于温带而非极地-古基因组改写冰期巨兽家谱" tabindex="-1">🦣 披毛犀起源于温带而非极地：古基因组改写冰期巨兽家谱 <a class="header-anchor" href="#🦣-披毛犀起源于温带而非极地-古基因组改写冰期巨兽家谱" aria-label="Permalink to &quot;🦣 披毛犀起源于温带而非极地：古基因组改写冰期巨兽家谱&quot;">​</a></h3><p><strong>Paleogenomics and habitat modeling reveal temperate Eurasian origins of woolly rhinoceroses</strong><em>Science（2026）</em></p><p>披毛犀是冰期巨型动物的代表，但其<strong>起源地</strong>与对冰期旋回的响应一直模糊。研究团队对欧亚大陆第四纪标本测序得到 <strong>29 个线粒体基因组 + 14 个核基因组</strong>，并对过去 <strong>50 万年</strong>的栖息地建模。结果显示，其<strong>母系遗传多样性主要在温带欧亚</strong>于约 <strong>46 万–42 万年前</strong>一次漫长的冰期—间冰期过渡中形成；一具约 <strong>17 万年前</strong>的东亚个体是<strong>所有后期种群的祖先</strong>，提示<strong>东亚是晚更新世支系的可能起源地</strong>；而<strong>阿尔泰地区</strong>则是重要的气候避难所。这凸显<strong>温带欧亚</strong>对披毛犀演化与耐寒巨兽多样化的关键作用，颠覆了&quot;寒冷驱动起源&quot;的直觉。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aed0430" target="_blank" rel="noreferrer">10.1126/science.aed0430</a></p><h3 id="⚛️-体材料中的-非厄米相变-euo-里动力学在例外点处质变" tabindex="-1">⚛️ 体材料中的&quot;非厄米相变&quot;：EuO 里动力学在例外点处质变 <a class="header-anchor" href="#⚛️-体材料中的-非厄米相变-euo-里动力学在例外点处质变" aria-label="Permalink to &quot;⚛️ 体材料中的&quot;非厄米相变&quot;：EuO 里动力学在例外点处质变&quot;">​</a></h3><p><strong>Discovery of an intrinsic non-Hermitian phase transition in a bulk condensed-matter system</strong><em>Science（2026）</em></p><p>常规相变发生在热平衡体系，而<strong>非厄米相变</strong>描述的是<strong>偏离平衡时动力学行为</strong>（而非稳态性质）在<strong>例外点（exceptional point）<strong>处的突变。本文在</strong>铁磁氧化铕（EuO）体材料</strong>中<strong>实验实现</strong>了它：光激发产生载流子后，在温度依赖的相互作用中，伴随<strong>厄米性的铁磁有序相变</strong>，出现<strong>非厄米性的弛豫动力学改变</strong>——时间分辨反射数据里表现为<strong>从双指数实衰减转为单指数复衰减</strong>。作者的理论模型能复现该行为，并<strong>推测非厄米相变可能在体材料中普遍出现</strong>，把这一此前多见于光学/开放量子系统的概念带入了常规凝聚态平台。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.ady4670" target="_blank" rel="noreferrer">10.1126/science.ady4670</a></p><h3 id="🦠-轮状病毒如何-打洞-入胞-冷冻电子断层扫描拍下全程" tabindex="-1">🦠 轮状病毒如何&quot;打洞&quot;入胞：冷冻电子断层扫描拍下全程 <a class="header-anchor" href="#🦠-轮状病毒如何-打洞-入胞-冷冻电子断层扫描拍下全程" aria-label="Permalink to &quot;🦠 轮状病毒如何&quot;打洞&quot;入胞：冷冻电子断层扫描拍下全程&quot;">​</a></h3><p><strong>Mechanism of membrane perforation in rotavirus cell entry</strong><em>Science（2026）</em></p><p>无包膜病毒入胞需要把一个大分子组装体<strong>穿越细胞膜</strong>，机制含糊。轮状病毒（双链 RNA 病毒）向宿主细胞送入<strong>内层衣壳颗粒</strong>后，不再脱壳，而是靠内部聚合酶与加帽活性<strong>外排带帽病毒 mRNA</strong>。作者用<strong>冷冻电子断层扫描（cryo-ET）<strong>可视化</strong>恒河猴轮状病毒入胞全程</strong>——从吸附、内吞到<strong>亚病毒颗粒释放</strong>；对分类后的亚颗粒做<strong>子断层平均</strong>，把<strong>病毒粒子的高分辨结构</strong>与<strong>活细胞荧光显微的时间序列</strong>关联起来，逐步给出了每一阶段的机制，<strong>包括把亚病毒颗粒递送进胞质的&quot;膜穿孔&quot;步骤</strong>。这为无包膜病毒的跨膜递送提供了结构性范式。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aeg4851" target="_blank" rel="noreferrer">10.1126/science.aeg4851</a></p><h3 id="🎱-二维台球是图灵完备的-物理系统中的不可判定轨迹" tabindex="-1">🎱 二维台球是图灵完备的：物理系统中的不可判定轨迹 <a class="header-anchor" href="#🎱-二维台球是图灵完备的-物理系统中的不可判定轨迹" aria-label="Permalink to &quot;🎱 二维台球是图灵完备的：物理系统中的不可判定轨迹&quot;">​</a></h3><p><strong>Two-dimensional billiards are Turing complete</strong><em>PNAS（2026）</em></p><p>台球系统是<strong>弹性反射粒子运动</strong>的理想化模型，也是<strong>陡峭约束势下光滑哈密顿系统</strong>的极限，并可<strong>精确改写硬球气体动力学</strong>。本文证明<strong>二维台球系统能模拟通用图灵机</strong>——借助图灵证明的<strong>停机问题不可判定性</strong>，直接推出在这类<strong>物理上自然的台球模型</strong>中会出现<strong>不可判定的轨迹</strong>。作者还类比讨论了与<strong>天体力学碰撞链极限</strong>的联系：近碰撞动力学呈现出<strong>台球式的符号轨道</strong>。这一结果把&quot;计算不可判定性&quot;锚定到一个纯物理力学系统，强化了&quot;物理过程即可计算过程&quot;的图景。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614500123" target="_blank" rel="noreferrer">10.1073/pnas.2614500123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧬-用-热力学遗传算法-驱动-llm-进化-t-gade-对抗种群多样性坍缩" tabindex="-1">🧬 用&quot;热力学遗传算法&quot;驱动 LLM 进化：T-GADE 对抗种群多样性坍缩 <a class="header-anchor" href="#🧬-用-热力学遗传算法-驱动-llm-进化-t-gade-对抗种群多样性坍缩" aria-label="Permalink to &quot;🧬 用&quot;热力学遗传算法&quot;驱动 LLM 进化：T-GADE 对抗种群多样性坍缩&quot;">​</a></h3><p><strong>T-GADE: Thermodynamical Generative-AI-Driven Evolution of LLM Artifacts</strong><em>arXiv（2026）</em></p><p>把 LLM 引入进化计算能实现候选项的<strong>语义级生成</strong>，但<strong>种群多样性维持</strong>这一经典难题依旧。作者效仿<strong>热力学遗传算法（TDGA）<strong>提出 <strong>T-GADE</strong>：保留种群与遗传算子概念，把 LLM 生成的</strong>结构化产物当作个体</strong>，用 LLM 算子实现交叉与变异；并引入 <strong>HoxLM</strong>——在评估后、生存选择前尝试<strong>自我修复</strong>个体；给出<strong>世代式与稳态式</strong>两种更新方案，以及 <strong>Fermi 型与 Bose 型占据规则</strong>来定义&quot;解同一性&quot;与是否允许重复。它把&quot;多样性 = 热力学熵&quot;这一物理直觉落到了 LLM 驱动的进化框架中（DOI 对应 arXiv:2609.12286）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.12286" target="_blank" rel="noreferrer">2609.12286</a></p><h3 id="🤖-claw-用超网络在测试时生成-lora-兼顾世界模型自适应的成本与表达力" tabindex="-1">🤖 CLAW：用超网络在测试时生成 LoRA，兼顾世界模型自适应的成本与表达力 <a class="header-anchor" href="#🤖-claw-用超网络在测试时生成-lora-兼顾世界模型自适应的成本与表达力" aria-label="Permalink to &quot;🤖 CLAW：用超网络在测试时生成 LoRA，兼顾世界模型自适应的成本与表达力&quot;">​</a></h3><p><strong>Amortized Low-Rank Adaptation for Model-Based Reinforcement Learning</strong><em>arXiv（2026）</em></p><p>世界模型让智能体通过预测行动后果来规划，但<strong>环境一变就不准</strong>。本文研究<strong>只用少数几条交互</strong>就把世界模型适配到未知测试环境（环境族已知）的问题：现有方法在<strong>算力开销</strong>与<strong>表达力</strong>间做取舍——上下文学习便宜但表达力弱，梯度适配强但昂贵。作者提出 <strong>CLAW（Context-conditioned Low-rank Adaptation of World models）</strong>：用<strong>超网络在测试时直接生成低秩（LoRA）适配器</strong>，预训练阶段<strong>模拟对多种环境的适配</strong>，联合训练超网络与基础世界模型。它把&quot;适配&quot;从在线优化摊薄（amortize）为一次前向，逼近了梯度适配的表达力而保留了上下文学习的廉价性（DOI 对应 arXiv:2609.12278）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.12278" target="_blank" rel="noreferrer">2609.12278</a></p><h3 id="🕸️-gt-bench-gta-llm-的图算法推理能力高度依赖-输入表示" tabindex="-1">🕸️ GT Bench + GTA：LLM 的图算法推理能力高度依赖&quot;输入表示&quot; <a class="header-anchor" href="#🕸️-gt-bench-gta-llm-的图算法推理能力高度依赖-输入表示" aria-label="Permalink to &quot;🕸️ GT Bench + GTA：LLM 的图算法推理能力高度依赖&quot;输入表示&quot;&quot;">​</a></h3><p><strong>GTA: Graph Theory Agent and Benchmark for Algorithmic Graph Reasoning with LLMs</strong><em>arXiv（2026）</em></p><p>LLM 越来越多被要求对<strong>图等结构化数据</strong>做推理，但它们在语言里执行<strong>多步图算法</strong>的可靠性不清；现有评测多用小图简单任务、只打分代码生成、或固定单一输入格式。作者提出 <strong>Graph Theory Bench（GT Bench）</strong>：覆盖 <strong>24 个经典图问题、44 种任务—结构组合、超过 10 万个样本</strong>，横跨<strong>自然语言、结构化语言、邻接表、邻接矩阵</strong>四种表示。评测 8 个 LLM 后发现：<strong>准确率与输入表示强相关</strong>，<strong>最佳表示随图密度、规模、拓扑及模型而变化</strong>，且这种敏感性在最强推理模型上<strong>依然存在（只是减弱）</strong>。这提示&quot;表示选择&quot;本身是被忽视的性能变量（DOI 对应 arXiv:2609.12265）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.12265" target="_blank" rel="noreferrer">2609.12265</a></p><h3 id="🔬-hypokg-llm-的生物医学假设-到底是在讲证据还是在讲好听的话" tabindex="-1">🔬 HypoKG：LLM 的生物医学假设&quot;到底是在讲证据还是在讲好听的话&quot; <a class="header-anchor" href="#🔬-hypokg-llm-的生物医学假设-到底是在讲证据还是在讲好听的话" aria-label="Permalink to &quot;🔬 HypoKG：LLM 的生物医学假设&quot;到底是在讲证据还是在讲好听的话&quot;&quot;">​</a></h3><p><strong>HypoKG: Evidence-Disciplined Biomedical Hypothesis Generation Beyond Endpoint Knowledge</strong><em>arXiv（2026）</em></p><p>LLM 能生成生物医学假设，但<strong>它是真在从证据推理，还是只产出听起来合理的想法</strong>，此前未有定论。作者把 <strong>KEGG、Rhea、UniProt</strong> 三大库合并成统一生化知识图谱，构建含 <strong>550 条&quot;酶来源→罕见病终点&quot;路径</strong>的基准，让 6 个 LLM 在<strong>四种信息条件</strong>（仅源酶 / 完整生物路径 / 仅源+疾病终点）下生成 <strong>13,200 条假设</strong>，再用<strong>专家五准则量表（每项 1–5 分）<strong>打分。关键发现：<strong>同时拿到源与疾病终点的模型常产出最高分假设</strong>——说明 LLM 能生成有说服力的想法，但</strong>这未必等于从完整机制链推理而来</strong>，构成对&quot;LLM 做科学发现&quot;的清醒校验（DOI 对应 arXiv:2609.12260）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.12260" target="_blank" rel="noreferrer">2609.12260</a></p><h3 id="💻-用-rag-让小模型本地跑科学代码助手-把算力负担挪出推理" tabindex="-1">💻 用 RAG 让小模型本地跑科学代码助手：把算力负担挪出推理 <a class="header-anchor" href="#💻-用-rag-让小模型本地跑科学代码助手-把算力负担挪出推理" aria-label="Permalink to &quot;💻 用 RAG 让小模型本地跑科学代码助手：把算力负担挪出推理&quot;">​</a></h3><p><strong>Retrieval-Augmented Generation for Scientific Code Understanding</strong><em>arXiv（2026）</em></p><p>当今一流编码助手（Claude Code、Codex）依赖<strong>超大规模云端模型</strong>，成本高且有<strong>数据隐私</strong>顾虑。本文探究：能否用<strong>小型开源模型</strong>搭出有用的<strong>全本地</strong>编码智能体——办法是<strong>把算力负担从推理挪到离线</strong>。系统严格分离两阶段：昂贵的<strong>离线摄取</strong>（解析、构建结构图、LLM 生成实体解释、嵌入）与轻量的<strong>在线问答</strong>。在 <strong>IPPL 科学代码库（C++）<strong>上，用覆盖 <strong>11 个类别、100 个问题</strong>的基准评测，并让</strong>独立前沿模型当裁判</strong>打分。它给出了一条&quot;<strong>离线重、在线轻</strong>&quot;的私有化代码理解路线（DOI 对应 arXiv:2609.12190）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.12190" target="_blank" rel="noreferrer">2609.12190</a></p><blockquote><p>📅 日期：2026-09-10 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const u=o(s,[["render",a]]);export{p as __pageData,u as default};
